import ijson
import json

from taf.analyzer.base import LogReader


from .emil_log_entry import EmilLogEntry
from .message import Message


class EmilReader(LogReader):

    def __init__(self, json_format="json", **kwargs):
        super(EmilReader, self).__init__(**kwargs)
        self._json_format = json_format

    def __iter__(self):

        if self._json_format == "json":
            for emil_entry in ijson.items(self._file_obj, 'emil_data.rows.item'):
                yield EmilLogEntry.parse(message=Message(emil_entry), timezone=self._timezone)

        elif self._json_format == "ndjson":
            for line in self._file_obj:
                emil_entry = json.loads(line)
                yield EmilLogEntry.parse(message=Message(emil_entry), timezone=self._timezone)

        else:
            raise ValueError("Invalid json format: {}".format(self._json_format))
